import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 승인해제 전표는 집계에서 제외하고 승인·마감 전표만 집계한다.
const EXCLUDED_STATUS = '승인해제';
// 가정: 부서 조건은 분개의 프로젝트가 속한 주관부서(project.department_id)로 거른다.
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function textOf(value: unknown): string {
  if (value === undefined || value === null) {
    return '';
  }
  return String(value).trim();
}

function intOf(value: unknown, label: string): number | null {
  const text = textOf(value);
  if (text === '') {
    return null;
  }
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
  }
  return Number(text);
}

@Controller('api/v1')
export class FnSfr01003Controller {
  @Get('/management-balance-sheets')
  async listManagementBalanceSheets(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const query = checks.queryOf(req.query);

    const baseDate = textOf(query['baseDate']);
    if (baseDate === '') {
      throw new ApiError(422, 'BASE_DATE_REQUIRED', '기준일을 입력해 주세요.');
    }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(baseDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '기준일 형식이 올바르지 않습니다.');
    }
    const projectId = intOf(query['projectId'], '프로젝트');
    const departmentId = intOf(query['departmentId'], '조직(부서)');
    const page = intOf(query['page'], '쪽') ?? 0;
    let size = intOf(query['size'], '건수') ?? DEFAULT_SIZE;
    if (size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '건수 값이 올바르지 않습니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }

    return transaction(async (db) => {
      const from =
        ' FROM voucher_line vl' +
        ' JOIN journal_voucher jv ON jv.journal_voucher_id = vl.journal_voucher_id' +
        ' JOIN account_item ai ON ai.account_item_id = vl.account_item_id' +
        ' LEFT JOIN project p ON p.project_id = vl.project_id' +
        ' WHERE jv.voucher_date <= CAST(:baseDate AS date)' +
        ' AND jv.status <> :excluded' +
        ' AND (CAST(:projectId AS bigint) IS NULL OR vl.project_id = CAST(:projectId AS bigint))' +
        ' AND (CAST(:departmentId AS bigint) IS NULL OR p.department_id = CAST(:departmentId AS bigint))';
      const filterParams = {
        baseDate,
        excluded: EXCLUDED_STATUS,
        projectId,
        departmentId,
      };

      const countRows = await db.query(
        'SELECT COUNT(*) AS "total" FROM (SELECT ai.account_item_id' + from + ' GROUP BY ai.account_item_id) t',
        filterParams,
      );
      const total = Number(countRows[0]['total']);

      const rows = await db.query(
        'SELECT ai.account_item_id AS "accountItemId",' +
          ' ai.account_code AS "accountCode",' +
          ' ai.account_name AS "accountName",' +
          ' SUM(vl.amount) AS "amount"' +
          from +
          ' GROUP BY ai.account_item_id, ai.account_code, ai.account_name' +
          ' ORDER BY ai.account_code' +
          ' LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { ...filterParams, size, offset: page * size },
      );

      const items = rows.map((row: Record<string, unknown>) => ({
        accountItemId: Number(row['accountItemId']),
        accountCode: row['accountCode'],
        accountName: row['accountName'],
        amount: Number(row['amount']),
      }));
      return { items, page, size, total };
    });
  }
}

