import { useState } from 'react';
import {
  call,
  useData,
  Num,
  Tiles,
  Filters,
  Field,
  DateInput,
  LookupSelect,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;

export default function FnSfr01003Page({ role, notify }: PageProps) {
  const [baseDate, setBaseDate] = useState<string>('');
  const [projectId, setProjectId] = useState<number | string>('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row | null>(null);
  const [page, setPage] = useState(0);
  const [message, setMessage] = useState('');
  const [selected, setSelected] = useState<Row | null>(null);

  const { data, error, loading } = useData<Page | undefined>(async () => {
    if (!applied) {
      return undefined;
    }
    return call<Page>('GET', '/management-balance-sheets', role, undefined, {
      ...applied,
      page,
      size: SIZE,
    });
  }, [applied, page, role]);

  const search = () => {
    if (!baseDate) {
      setMessage('기준일을 선택해 주세요.');
      return;
    }
    setMessage('');
    setPage(0);
    setApplied({ baseDate, projectId, departmentId });
  };

  const reset = () => {
    setBaseDate('');
    setProjectId('');
    setDepartmentId('');
    setApplied(null);
    setPage(0);
    setMessage('');
    notify('조회 조건을 초기화했습니다.');
  };

  const rows = data ? data.items : [];
  const pageTotal = rows.reduce((sum, row) => sum + Number(row['amount'] ?? 0), 0);

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>집계 요약</h2>
        <Tiles
          items={[
            ['계정과목 수', <Num value={data ? data.total : 0} />],
            ['현재 쪽 금액 합계', <Num value={pageTotal} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>관리용 재무상태표</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 기준일" required>
            <DateInput value={baseDate} onChange={setBaseDate} />
          </Field>
          <Field label="프로젝트">
            <LookupSelect table="project" role={role} value={projectId} onChange={setProjectId} />
          </Field>
          <Field label="조직(부서)">
            <LookupSelect table="department" role={role} value={departmentId} onChange={setDepartmentId} />
          </Field>
        </Filters>
        {message ? <ErrorText text={message} /> : null}
        {error ? <ErrorText text={error} /> : null}
        <Band total={data ? data.total : 0} />
        <DataTable
          columns={[
            { key: 'accountCode', label: '계정과목 코드' },
            { key: 'accountName', label: '계정과목 명칭' },
            { key: 'amount', label: '계정과목별 집계 금액', render: (row: Row) => <Num value={row['amount']} /> },
          ]}
          rows={rows}
          onRowClick={(row: Row) => setSelected(row)}
          empty={loading ? '불러오는 중입니다.' : applied ? '조회된 내역이 없습니다.' : '기준일을 선택하고 조회해 주세요.'}
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      {selected ? (
        <Drawer title="계정과목 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['계정과목 코드', String(selected['accountCode'] ?? '')],
              ['계정과목 명칭', String(selected['accountName'] ?? '')],
              ['계정과목별 집계 금액', <Num value={selected['amount']} />],
            ]}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
